sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var reqSysId = current.getValue('document_id') || current.getValue('sysapproval');
    if (!reqSysId) return;

    // Check if any approval is still pending for this request
    var pendingApprovals = new GlideRecord('sysapproval_approver');
    pendingApprovals.addQuery('document_id', reqSysId);
    pendingApprovals.addQuery('state', 'IN', 'requested,not_yet_requested');
    pendingApprovals.query();

    if (pendingApprovals.hasNext()) {
        // Earlier level approved, but higher tier is still pending
        return;
    }

    // ── ALL APPROVALS COMPLETE: FINALIZE RECORD ──
    var reqGr = new GlideRecord('x_birl3_clm_key_group_code_request');
    if (!reqGr.get(reqSysId)) return;

    var gCode = reqGr.getValue('group_code');
    var gpCode = reqGr.getValue('grandparent_code');
    var requestedLimit = parseFloat(reqGr.getValue('total_requested_limit')) || 0;

    // 1. Mark request approved and set approved limit
    reqGr.setValue('state', 'Approved');
    reqGr.setValue('approved_limit', requestedLimit);

    // 2. Cascade approved limits to Site Master records
    var draftGr = new GlideRecord('x_birl3_clm_p1_crm_site_draft');
    draftGr.addQuery('target_request', reqSysId);
    draftGr.addQuery('justification', 'Central SPOC Finalized Values');
    draftGr.query();

    while (draftGr.next()) {
        var siteCode = draftGr.getValue('site_code');
        var approvedSiteLimit = parseFloat(draftGr.getValue('desired_limit')) || 0;
        var siteTenor = parseInt(draftGr.getValue('credit_tenor'), 10) || 45;
        var orderRate = parseFloat(draftGr.getValue('order_rate')) || 0;
        var sobQty = parseFloat(draftGr.getValue('expected_sob_qty')) || 0;

        var siteMaster = new GlideRecord('x_birl3_clm_key_customer');
        siteMaster.addQuery('site_code', siteCode);
        siteMaster.query();
        if (siteMaster.next()) {
            siteMaster.setValue('credit_limit', approvedSiteLimit);
            siteMaster.setValue('credit_tenor', siteTenor);
            siteMaster.setValue('order_rate', orderRate);
            siteMaster.setValue('expected_sob_qty', sobQty);
            siteMaster.update();
        }
    }

    // 3. Recalculate exposures from updated site limits and active BG
    var totalGrpLimit = 0;
    var totalGrpBg = 0;
    var grpSites = new GlideRecord('x_birl3_clm_key_customer');
    grpSites.addQuery('group_code', gCode);
    grpSites.query();
    while (grpSites.next()) {
        totalGrpLimit += (parseFloat(grpSites.getValue('credit_limit')) || 0);
        totalGrpBg += (parseFloat(grpSites.getValue('active_bg')) || 0);
    }
    var finalGroupNetExposure = totalGrpLimit - totalGrpBg;

    var totalGpLimit = 0;
    var totalGpBg = 0;
    var gpSites = new GlideRecord('x_birl3_clm_key_customer');
    gpSites.addQuery('grandparent_code', gpCode);
    gpSites.query();
    while (gpSites.next()) {
        totalGpLimit += (parseFloat(gpSites.getValue('credit_limit')) || 0);
        totalGpBg += (parseFloat(gpSites.getValue('active_bg')) || 0);
    }
    var finalGpNetExposure = totalGpLimit - totalGpBg;

    reqGr.setValue('group_net_exposure', finalGroupNetExposure);
    reqGr.setValue('grandparent_net_exposure', finalGpNetExposure);
    reqGr.update();

})(current, previous);
